import { getMaxSoloMoves } from './floodLogic';

/**
 * Solo balance table — solver-calibrated limits and pars per config.
 *
 * Calibrated by `npm run sim` (scripts/sim.ts):
 *  - PAR_MOVES: median moves the beam-8 solver needs on deterministic seeded boards.
 *    3 stars: moves <= par.
 *  - SOLO_LIMITS: allowed move count, set so a competent player (width-4 beam proxy)
 *    wins >= 90% of boards at every config, while easy configs stay non-trivial.
 *    2 stars: moves <= midpoint of [par, limit]; 1 star: any other win.
 *
 * The tables below are generated by `npm run sim -- --persist` and verified by
 * `npm run sim -- --verify`. Do not hand-edit; change calibration in scripts/sim.ts.
 */

