SOLO_LIMITS.set('18:8', 44);

const key = (size: number, colors: number) => `${size}:${colors}`;

export const maxSoloMovesLimit = (size: number, colors: number): number =>
  SOLO_LIMITS.get(key(size, colors)) ?? getMaxSoloMoves(size, colors);

export const soloPar = (size: number, colors: number): number =>
  PAR_MOVES.get(key(size, colors)) ?? maxSoloMovesLimit(size, colors);

export type SoloStars = 1 | 2 | 3;

export const rateSoloStars = (moves: number, size: number, colors: number): SoloStars => {
  const par = soloPar(size, colors);
  const limit = maxSoloMovesLimit(size, colors);
  if (moves <= par) return 3;
  const midpoint = Math.min(limit, par + Math.ceil((limit - par) / 2));
  if (moves <= midpoint) return 2;
  return 1;
};
